 "content": "def transform(grid):
    """Fill background cells between consecutive markers along rows or columns."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = min(set(v for row in grid for v in row))
    # The marker is the non-background color; background is the most frequent color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    candidates = [v for v in counts if v != bg]
    if len(candidates) != 1:
        # ARC instances here use a single sparse marker color.
        marker = min(candidates, key=lambda v: counts[v])
    else:
        marker = candidates[0]
    fill = 3
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
